def conv(value, kind: str):
    """Normalize a database value into the API record shape."""
    if value is None:
        return None
    if kind == "num" and isinstance(value, Decimal):
        return float(value)
    if kind in ("date", "ts") and isinstance(value, (date, datetime)):
        return value.isoformat()
    return value
